styles.css:
display: inline-flex;
align-items: center;
justify-content: center;
padding: var(--wp--preset--spacing--20);
border: 1px solid color-mix(in srgb, var(--wp--custom--color--icon--background) 35%, transparent);
border-radius: var(--wp--preset--border-radius--200);
background: var(--wp--custom--color--icon--background);
box-sizing: border-box;
overflow: hidden;
line-height: 0;

& .wp-block-outermost-icon-block {
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 auto;
	margin: 0;
	line-height: 0;
	color: var(--wp--custom--color--icon--color);
}

& .icon-container {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	background: transparent !important;
	color: var(--wp--custom--color--icon--color) !important;
}

& .icon-container svg {
	fill: currentColor;
}
